/**
 * Exact cross-sections of every reference node.
 *
 * GENERATED by scripts/emit-cross-sections.py from scripts/slice-exact.py. Do not hand-edit:
 * re-run the extractor and regenerate, so the file always matches the parameters that produced it.
 *
 * HOW THESE ARE MEASURED, AND WHY IT CHANGED. The previous extractor inferred each section
 * statistically -- it dropped a height band's vertices into angular bins and took the 0.92 percentile
 * of each bin's radius. A bin holds between 3 and 270 points on this asset, and the 0.92 percentile
 * of 3 points IS the maximum while the 0.92 percentile of 270 is a real quantile, so neighbouring
 * bins carried different upward bias and the BIAS wobbled ring to ring: second differences of 15-26%
 * of the mean radius on every part. That wobble was the crumpling that survived to 1.6M triangles.
 *
 * A cross-section is not a statistic. It is the intersection of a plane with a mesh, and these are
 * computed that way: every triangle crossing the plane gives an exact segment, the segments chain
 * into closed loops, and each loop is resampled from its own centroid. Measured, that took surface
 * noise from 1.61x the reference to 1.26x with the silhouette unchanged, and the skin region from
 * 1.48x to 1.02x -- indistinguishable from the reference.
 *
 * Separate loops ARE separate clusters, so the grid connected-components pass and its 15 mm cell are
 * gone: two skirt panels, two legs and two shoulder caps come out distinct by construction.
 *
 * Open arcs survive this change, and an attempt to remove them is recorded here so it is not
 * repeated. The reasoning was that an exact slice through a sheet is a thin CLOSED loop, which is
 * true of a FLAT sheet -- its centroid lies on it and rays reach it in every direction. It is false
 * of a CURVED one: the cape panels put their centroid in the air beside the arc, so most of the
 * circle has no surface, and closing the ring made the back panel 36 mm thick and rendered it as a
 * cylinder standing between the panels. Arcs are now decided by exact ray coverage rather than by a
 * percentile's guess at it, which is what makes them reliable.
 */

export interface Ring {
  /** Index of the reference node this ring was measured from. */
  readonly node: number;
  /** The part's OWN dominant axis: 0 = x, 1 = y, 2 = z. Eleven nodes are not vertical. */
  readonly axis: 0 | 1 | 2;
  /** Position along the slicing axis. */
  readonly t: number;
  readonly centroid: readonly [number, number];
  readonly points: readonly (readonly [number, number])[];
  /**
   * [first directly-hit spoke, run length] when this section is an ARC rather than a closed outline.
   *
   * A FLAT sheet has its centroid on the sheet, so an exact slice of it really is a thin closed loop.
   * A CURVED sheet -- a cape panel, a coat tail -- has its centroid in the AIR beside the arc, so
   * rays reach it over only part of the circle and the extractor's gap-filling bridges the empty
   * side. Closing that bridge makes a solid: measured, the cape's back panel came out 36 mm thick
   * against a few millimetres of cloth and rendered as a cylinder standing between the panels.
   */
  readonly arc?: readonly [number, number];
}

export const SECTION_BANDS = 80;
export const SECTION_SPOKES = 48;

