const POS_SCALE = 16000;
const RAD_SCALE = 65535;

/** Decode once at module load. */
function unpack(): Ring[] {
  const binary = atob(PACKED);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i += 1) bytes[i] = binary.charCodeAt(i);
  const view = new DataView(bytes.buffer);
  const stride = 10 + SECTION_SPOKES * 2;
  const out: Ring[] = [];
  for (let offset = 0; offset + stride <= bytes.length; offset += stride) {
    const node = view.getUint8(offset);
    const axis = view.getUint8(offset + 1) as 0 | 1 | 2;
    const arcStart = view.getUint8(offset + 2);
    const arcLength = view.getUint8(offset + 3);
    const t = view.getInt16(offset + 4, true) / POS_SCALE;
    const cx = view.getInt16(offset + 6, true) / POS_SCALE;
    const cz = view.getInt16(offset + 8, true) / POS_SCALE;
    const points: Array<readonly [number, number]> = [];
    for (let k = 0; k < SECTION_SPOKES; k += 1) {
      const radius = view.getUint16(offset + 10 + k * 2, true) / RAD_SCALE;
      // Spokes sit at bin CENTRES, matching the extractor, so ring i point k and ring i+1 point k
      // came from the same ray angle and the loft between them cannot twist.
      const angle = -Math.PI + (k + 0.5) * 2 * Math.PI / SECTION_SPOKES;
      points.push([cx + radius * Math.cos(angle), cz + radius * Math.sin(angle)]);
    }
    out.push(arcLength > 0
      ? { node, axis, t, centroid: [cx, cz], points, arc: [arcStart, arcLength] }
      : { node, axis, t, centroid: [cx, cz], points });
  }
  return out;
}

export const SECTIONS: readonly Ring[] = unpack();
